name: formal / bounded state model

on:
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

jobs:
  bounded-model:
    runs-on: ubuntu-latest
    timeout-minutes: 5
    env:
      MODEL: lease-supervisor
      INITIAL: idle
      TERMINAL: stopped
      EDGES: idle|start|starting;starting|activate|active;starting|stop|stopped;active|drain|draining;active|stop|stopped;draining|stop|stopped
    steps:
      - name: Exhaustively check state-machine invariants
        shell: bash
        run: |
          node <<'NODE'
          const edges=process.env.EDGES.split(";").map(x=>{const [f,e,t]=x.split("|");return{f,e,t}});
          const terminal=new Set(process.env.TERMINAL.split(",").filter(Boolean));
          const events=[...new Set(edges.map(x=>x.e))], k=s=>JSON.stringify([s.p,s.v,s.id,s.e,s.n]);
          const same=(a,b)=>k(a)===k(b), inv=(q,m,c)=>{if(!q)throw Error(m+"\n"+JSON.stringify(c))};
          function step(s,c){const b={...s};if(c.id===s.id)return c.e===s.e?{a:1,r:1,b,n:{...s},c}:{a:0,r:0,b,n:{...s},c};if(c.v!==s.v||terminal.has(s.p))return{a:0,r:0,b,n:{...s},c};const z=edges.find(z=>z.f===s.p&&z.e===c.e);if(!z)return{a:0,r:0,b,n:{...s},c};return{a:1,r:0,b,n:{p:z.t,v:s.v+1,id:c.id,e:c.e,n:s.n+(terminal.has(z.t)?1:0)},c}}
          function check(t){inv(t.n.v>=t.b.v,"version regressed",t);inv(t.n.n<=1,"multiple terminal outcomes",t);if(t.a&&!t.r)inv(t.n.v===t.b.v+1,"accepted mutation must advance one version",t);else inv(same(t.b,t.n),"rejected/replayed command changed state",t);if(terminal.has(t.b.p))inv(!t.a||t.r,"terminal state mutated",t)}
          const start={p:process.env.INITIAL,v:0,id:null,e:null,n:0},q=[start],seen=new Map([[k(start),start]]);let i=0,checked=0;
          while(i<q.length){const s=q[i++];inv(s.n===(terminal.has(s.p)?1:0),"terminal accounting mismatch",s);const cs=[];for(const e of events)cs.push({id:e+":"+s.v,e,v:s.v},{id:"stale:"+e+":"+s.v,e,v:s.v-1});if(s.id)cs.push({id:s.id,e:s.e,v:s.v},{id:s.id,e:events.find(e=>e!==s.e)||s.e,v:s.v});for(const c of cs){const t=step(s,c);checked++;check(t);if(t.a&&!t.r){const z=k(t.n);if(!seen.has(z)){seen.set(z,t.n);q.push(t.n)}}}}
          console.log(JSON.stringify({model:process.env.MODEL,claim:"finite-exhaustive-lifecycle-abstraction",states:seen.size,transitions:checked,invariants:["version-monotonicity","rejection-side-effect-freedom","terminal-absorption","exact-replay-idempotence","ambiguous-id-rejection","at-most-one-terminal-outcome"]}));
          NODE

//! Bounded model checker for durable critical-section failover.
//! The model focuses on fencing/lease handoff, not Redis implementation details.

use std::collections::{HashSet, VecDeque};

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Holder {
    None,
    A,
    B,
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum RequestId {
    None,
    R1,
    R2,
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct State {
    now: u8,
    current_owner_epoch: u8,
    lease_owner_epoch: u8,
    sequence: u8,
    holder: Holder,
    request_id: RequestId,
    expires_at: u8,
    inherited: bool,
}

#[derive(Clone, Copy, Debug)]
enum Action {
    Tick,
    Failover,
    Acquire { holder: Holder, request_id: RequestId },
    Renew { holder: Holder, owner_epoch: u8, sequence: u8 },
    Release { holder: Holder, owner_epoch: u8, sequence: u8 },
}

const MAX_TIME: u8 = 4;
const MAX_OWNER_EPOCH: u8 = 3;
const MAX_SEQUENCE: u8 = 4;
const LEASE: u8 = 2;

fn initial() -> State {
    State {
        now: 0,
        current_owner_epoch: 1,
        lease_owner_epoch: 0,
        sequence: 0,
        holder: Holder::None,
        request_id: RequestId::None,
        expires_at: 0,
        inherited: false,
    }
}

fn expire(mut s: State) -> State {
    if s.holder != Holder::None && s.now >= s.expires_at {
        s.holder = Holder::None;
        s.request_id = RequestId::None;
        s.expires_at = 0;
        s.inherited = false;
    }
    s
}

fn valid_holder(holder: Holder) -> bool {
    matches!(holder, Holder::A | Holder::B)
}

fn owns(s: State, holder: Holder, owner_epoch: u8, sequence: u8) -> bool {
    s.holder == holder
        && !s.inherited
        && s.lease_owner_epoch == owner_epoch
        && s.current_owner_epoch == owner_epoch
        && s.sequence == sequence
        && s.now < s.expires_at
}

fn invariant(s: State) -> bool {
    if s.current_owner_epoch == 0 || s.current_owner_epoch > MAX_OWNER_EPOCH {
        return false;
    }
    if s.sequence > MAX_SEQUENCE {
        return false;
    }
    match s.holder {
        Holder::None => s.expires_at == 0 && !s.inherited && s.request_id == RequestId::None,
        Holder::A | Holder::B => {
            s.expires_at > s.now
                && s.request_id != RequestId::None
                && s.lease_owner_epoch > 0
                && s.lease_owner_epoch <= s.current_owner_epoch
                && (!s.inherited || s.lease_owner_epoch < s.current_owner_epoch)
                && (s.inherited || s.lease_owner_epoch == s.current_owner_epoch)
        }
    }
}

fn step(input: State, action: Action) -> Option<State> {
    let s = expire(input);
    let next = match action {
        Action::Tick if s.now < MAX_TIME => expire(State { now: s.now + 1, ..s }),
        Action::Failover if s.current_owner_epoch < MAX_OWNER_EPOCH => {
            let inherited = s.holder != Holder::None;
            State {
                current_owner_epoch: s.current_owner_epoch + 1,
                inherited,
                ..s
            }
        }
        Action::Acquire { holder, request_id }
            if valid_holder(holder)
                && request_id != RequestId::None
                && s.holder == Holder::None
                && s.sequence < MAX_SEQUENCE =>
        {
            State {
                holder,
                request_id,
                lease_owner_epoch: s.current_owner_epoch,
                sequence: s.sequence + 1,
                expires_at: (s.now + LEASE).min(MAX_TIME + LEASE),
                inherited: false,
                ..s
            }
        }
        Action::Acquire { holder, request_id }
            if valid_holder(holder)
                && request_id != RequestId::None
                && !s.inherited
                && s.holder == holder
                && s.request_id == request_id =>
        {
            // Idempotent replay: no new fence and no TTL extension.
            s
        }
        Action::Renew {
            holder,
            owner_epoch,
            sequence,
        } if owns(s, holder, owner_epoch, sequence) => State {
            expires_at: (s.now + LEASE).min(MAX_TIME + LEASE),
            ..s
        },
        Action::Release {
            holder,
            owner_epoch,
            sequence,
        } if owns(s, holder, owner_epoch, sequence) => State {
            holder: Holder::None,
            request_id: RequestId::None,
            expires_at: 0,
            inherited: false,
            ..s
        },
        _ => return None,
    };
    assert!(
        next.current_owner_epoch >= input.current_owner_epoch,
        "owner epoch regressed: {:?} -> {:?}", input, next
    );
    assert!(
        invariant(next),
        "invalid state: {:?} --{:?}--> {:?}",
        input,
        action,
        next
    );
    Some(next)
}

fn actions() -> Vec<Action> {
    let mut out = vec![Action::Tick, Action::Failover];
    for holder in [Holder::A, Holder::B] {
        for request_id in [RequestId::R1, RequestId::R2] {
            out.push(Action::Acquire { holder, request_id });
        }
        for owner_epoch in 1..=MAX_OWNER_EPOCH {
            for sequence in 1..=MAX_SEQUENCE {
                out.push(Action::Renew {
                    holder,
                    owner_epoch,
                    sequence,
                });
                out.push(Action::Release {
                    holder,
                    owner_epoch,
                    sequence,
                });
            }
        }
    }
    out
}

fn main() {
    let initial = initial();
    assert!(invariant(initial));
    let mut seen = HashSet::from([initial]);
    let mut queue = VecDeque::from([initial]);
    let mut transitions = 0usize;

    while let Some(state) = queue.pop_front() {
        for action in actions() {
            if let Some(next) = step(state, action) {
                transitions += 1;
                if seen.insert(next) {
                    queue.push_back(next);
                }
            }
        }
    }

    // Witness the key failover shape: an active old lease is inherited under
    // a newer owner epoch and cannot become a fresh grant until it expires.
    assert!(seen.iter().any(|s| {
        s.inherited
            && s.holder != Holder::None
            && s.lease_owner_epoch < s.current_owner_epoch
    }));
    assert!(seen.iter().any(|s| {
        s.current_owner_epoch >= 2
            && !s.inherited
            && s.holder != Holder::None
            && s.lease_owner_epoch == s.current_owner_epoch
    }));

    // Same request can replay only while the same owner still owns the live
    // lease. A failover marks the lease inherited, disabling replay until
    // persisted expiry.
    let granted = State {
        now: 0,
        current_owner_epoch: 1,
        lease_owner_epoch: 1,
        sequence: 1,
        holder: Holder::A,
        request_id: RequestId::R1,
        expires_at: 2,
        inherited: false,
    };
    assert_eq!(
        step(
            granted,
            Action::Acquire {
                holder: Holder::A,
                request_id: RequestId::R1,
            }
        ),
        Some(granted),
    );
    assert_eq!(
        step(
            granted,
            Action::Acquire {
                holder: Holder::A,
                request_id: RequestId::R2,
            }
        ),
        None,
    );
    let failed_over = step(granted, Action::Failover).expect("failover");
    assert!(failed_over.inherited);
    assert_eq!(
        step(
            failed_over,
            Action::Acquire {
                holder: Holder::A,
                request_id: RequestId::R1,
            }
        ),
        None,
    );

    println!(
        "bmscl critical-section formal model: explored {} states / {} transitions; invariants hold",
        seen.len(),
        transitions
    );
}

//! Bounded model checker for hot-reload supervisor handoff.
//! Proves, for the modeled transition system, that routing never targets a dead
//! generation and the old generation is not stopped before traffic moves.

use std::collections::{HashSet, VecDeque};

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Route { Old, New }

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
struct State {
    old_live: bool,
    new_live: bool,
    route: Route,
    draining_old: bool,
}

fn invariant(s: State) -> bool {
    let route_is_live = match s.route { Route::Old => s.old_live, Route::New => s.new_live };
    let drain_after_handoff = !s.draining_old || s.route == Route::New;
    route_is_live && drain_after_handoff && (s.old_live || s.new_live)
}

fn next(s: State) -> Vec<State> {
    let mut out = Vec::new();
    if !s.new_live {
        out.push(State { new_live: true, ..s });
    }
    if s.new_live && s.route == Route::Old {
        out.push(State { route: Route::New, ..s });
    }
    if s.route == Route::New && s.old_live && !s.draining_old {
        out.push(State { draining_old: true, ..s });
    }
    if s.draining_old && s.old_live {
        out.push(State { old_live: false, draining_old: false, ..s });
    }
    out
}

fn main() {
    let initial = State { old_live: true, new_live: false, route: Route::Old, draining_old: false };
    let mut seen = HashSet::from([initial]);
    let mut queue = VecDeque::from([initial]);
    while let Some(state) = queue.pop_front() {
        assert!(invariant(state), "invalid supervisor state: {state:?}");
        for candidate in next(state) {
            assert!(invariant(candidate), "unsafe handoff: {state:?} -> {candidate:?}");
            if seen.insert(candidate) { queue.push_back(candidate); }
        }
    }
    assert!(seen.iter().any(|s| !s.old_live && s.new_live && s.route == Route::New));
    println!("bmscl-supervisor formal model: explored {} states; invariants hold", seen.len());
}
